// Generated by secure-by-design v0.1.0 for DPDP §8(7) (Retention).
// Maps to: ISO 27001 A.8.10 (Information Deletion).
// Reads from ../../privacy-security-manifest.yaml.
// Safe to modify. Safe to delete. Re-run /sbd-deploy to regenerate.
// Docs: docs/scaffolds/retention-runner.md
//
// Runs daily (or on-demand). For each dataCategory in the manifest, finds
// records past their retentionDays and either erases or anonymizes them.

import { auditLog } from '../security/audit_log';

export interface RetentionRule {
  category: string;          // matches manifest.dataCategories[].name
  retentionDays: number;
  table: string;             // your table / collection / model name
  timestampField: string;    // the column that anchors retention (createdAt, lastAccessedAt, consent expiry)
  strategy: 'hard-delete' | 'anonymize' | 'soft-delete-then-purge';
  // 'soft-delete-then-purge' marks deleted=true at retentionDays, hard-deletes after legalHoldDays.
  legalHoldDays?: number;
}

export interface RetentionAdapter {
  /**
   * Apply the rule. Implementation talks to your ORM / database.
   * Must return counts so the runner can emit a structured audit event.
   */
  apply(rule: RetentionRule, now: Date): Promise<{
    inspected: number;
    erased: number;
    anonymized: number;
    softDeleted: number;
    skippedLegalHold: number;
  }>;
}

let adapter: RetentionAdapter | null = null;
export function setRetentionAdapter(a: RetentionAdapter): void { adapter = a; }

export async function runRetention(rules: RetentionRule[], when: Date = new Date()): Promise<void> {
  if (!adapter) throw new Error('secure-by-design: RetentionAdapter not configured.');

  for (const rule of rules) {
    try {
      const result = await adapter.apply(rule, when);
      await auditLog.event('retention.run', {
        actor: 'system:retention-runner',
        target: rule.category,
        attrs: {
          table: rule.table,
          strategy: rule.strategy,
          retentionDays: rule.retentionDays,
          ...result,
        },
      });
    } catch (e) {
      await auditLog.event('retention.run', {
        actor: 'system:retention-runner',
        target: rule.category,
        severity: 'ERROR',
        outcome: 'failure',
        attrs: { error: e instanceof Error ? e.message : 'unknown' },
      });
      // Continue — one rule failing should not stop the others.
    }
  }
}

/**
 * Helper to schedule daily runs. Wire to your job runner (cron, BullMQ, Temporal).
 */
export function dailyRetentionTask(rules: RetentionRule[]): () => Promise<void> {
  return () => runRetention(rules);
}
